def apply_cell_flip(grid, flip_horizontal, flip_vertical):
    """Apply flip transformations to this grid while preserving separator lines"""
    new_grid = [[cell for cell in row] for row in grid]

    # Find all border rows and columns
    # We keep rows 6, 17, 19 and cols 4, 13, 24, 28 as is
    hrefs = set(horiz_sep)
    vertfs = set(vert_sep)

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 4 and (i in hrefs or j in vertfs):
                continue  # Keep separators as is

            # Determine which region this cell belongs to
            # Row region: from last separator to next separator
            row_region_start = i
            for href in sorted(hrefs):
                if href < i:
                    row_region_start = href
                else:
                    break
            row_region_end = i
            for href in sorted(hrefs):
                if href > i:
                    row_region_end = href
                else:
                    break

            col_region_start = j
            for vertf in sorted(vertfs):
                if vertf < j:
                    col_region_start = vertf
                else:
                    break
            col_region_end = j
            for vertf in sorted(vertfs):
                if vertf > j:
                    col_region_end = vertf
                else:
                    break

            # Flip the content within the region
            # Horizontal flip: swap left and right
            if flip_horizontal:
                col_to_get = len(grid[0]) - 1 - j
                new_grid[i][j] = grid[i][col_to_get]
            # Vertical flip: swap top and bottom
            elif flip_vertical:
                row_to_get = len(grid) - 1 - i
                new_grid[i][j] = grid[row_to_get][j]
            else:
                new_grid[i][j] = grid[i][j]

    return new_grid

